import datetime

def derive(record):
    derived = {}

    # Determine if the study is an applicable clinical trial based on the definitions
    derived['is_applicable_trial'] = False
    design_module = record.get('protocolSection', {}).get('designModule', {})
    oversight_module = record.get('protocolSection', {}).get('oversightModule', {})

    if design_module.get('studyType') == 'INTERVENTIONAL':
        if oversight_module.get('isFdaRegulatedDevice') or any(location['country'] == 'United States' for location in record.get('protocolSection', {}).get('contactsLocationsModule', {}).get('locations', [])):
            derived['is_applicable_trial'] = True
        elif oversight_module.get('isFdaRegulatedDrug') or any(location['country'] == 'United States' for location in record.get('protocolSection', {}).get('contactsLocationsModule', {}).get('locations', [])):
            derived['is_applicable_trial'] = True

    # Calculate the submission deadline
    primary_completion_date = record.get('protocolSection', {}).get('statusModule', {}).get('primaryCompletionDateStruct', {}).get('date')
    if primary_completion_date:
        try:
            pc_date = datetime.datetime.strptime(primary_completion_date, "%Y-%m-%d")
            derived['submission_deadline'] = (pc_date + datetime.timedelta(days=365)).strftime("%Y-%m-%d")
        except ValueError:
            derived['submission_deadline'] = None

    return derived
